        }
        if (saveTerms) {
          const view = await this.api.setTerms(sheet, terms);
          this.session.terms.set(view.terms);
        }
        for (const t of saveGradeTerms) {
          const view = await this.api.setGradeTerms(sheet, t.grade, t.value);
